'use client';

import { BookOpen, Bot, CalendarClock, ChevronDown, Clock, FileText, MessagesSquare, PanelLeft, Repeat, Sparkles, UserRound, Workflow, Wrench, Zap } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { useAgentsBuilder } from '@/components/ui/agents-builder/agents-builder-context';
import { CanvasNode, Dot, Instructions, NODE_WIDTH, NodeCard, NodeRow, RowIcon } from '@/components/ui/agents-builder/canvas-nodes';
import { CanvasWires } from '@/components/ui/agents-builder/canvas-wires';
import { IntegrationMark } from '@/components/ui/agents-builder/integration-mark';
import { useReducedMotion } from '@/components/ui/agents-builder/playback';
import { CanvasSurface, CanvasZoomControls, useCanvasViewport } from '@/components/ui/workspace-kit/canvas';
import { focusRingClass, ToneBadge, TooltipIconButton } from '@/components/ui/workspace-kit/primitives';
import type { AgentRunState, NodeStage } from '@/components/ui/agents-builder/use-agent-run';

/** Left edge of each column: inputs, the agent, outputs. */
const COLUMNS = [0, 343, 686] as const;
const CONTENT_WIDTH = COLUMNS[2] + NODE_WIDTH;
/** Tools listed before "Show N more". */
const TOOL_PREVIEW = 4;
/** Lets a node finish its ready transition before the view eases to it. */
const REVEAL_AFTER_READY_MS = 300;

/** Remembers which nodes are collapsed; everything starts open. */
function useCollapsed() {
	const [collapsed, setCollapsed] = React.useState<ReadonlySet<string>>(() => new Set());
	const toggle = React.useCallback(
		(id: string) =>
			setCollapsed((current) => {
				const next = new Set(current);
				if (next.has(id)) next.delete(id);
				else next.add(id);
				return next;
			}),
		[],
	);
	return { isOpen: (id: string) => !collapsed.has(id), toggle, key: [...collapsed].sort().join() };
}

/** Eases the view to a run node whenever it appears or finishes loading. */
function useRevealOnStage(stages: AgentRunState['nodes'], layerRef: React.RefObject<HTMLDivElement | null>, reveal: (node: Element) => void) {
	const previous = React.useRef(stages);
	React.useEffect(() => {
		const before = previous.current;
		previous.current = stages;
		const changed = (Object.keys(stages) as (keyof typeof stages)[]).find(
			(key) => stages[key] !== before[key] && stages[key] !== 'absent',
		);
		if (!changed) return;
		const timer = window.setTimeout(
			() => {
				const node = layerRef.current?.querySelector(`[data-node-id="${changed}"]`);
				if (node) reveal(node);
			},
			stages[changed] === 'ready' ? REVEAL_AFTER_READY_MS : 0,
		);
		return () => window.clearTimeout(timer);
	}, [layerRef, reveal, stages]);
}

type AgentCanvasProps = {
	state: AgentRunState;
	panelOpen: boolean;
	onTogglePanel: () => void;
};

/**
 * Pannable, zoomable map of an agent: inputs (schedule, triggers, channels,
 * memory) wire into the agent, which fans out to tools, sub-agents, and
 * skills. Nodes appear as the run reaches them, and the view eases to keep
 * each new node on screen.
 */
function AgentCanvas({ state, panelOpen, onTogglePanel }: AgentCanvasProps) {
	const { currentAgent, integration, emit } = useAgentsBuilder();
	const { agent } = currentAgent;
	const layerRef = React.useRef<HTMLDivElement>(null);
	const viewport = useCanvasViewport(CONTENT_WIDTH);
	const nodes = useCollapsed();
	const [moreTools, setMoreTools] = React.useState(false);
	const reducedMotion = useReducedMotion();

	useRevealOnStage(state.nodes, layerRef, viewport.reveal);

	const node = (
		id: string,
		title: string,
		icon: React.ComponentProps<typeof CanvasNode>['icon'],
		extra: { tone?: 'new'; meta?: React.ReactNode; badge?: React.ReactNode; stage?: NodeStage } = {},
	) => ({
		id,
		title,
		icon,
		open: nodes.isOpen(id),
		onToggle: () => nodes.toggle(id),
		...extra,
	});
	const tools = moreTools ? agent.tools : agent.tools.slice(0, TOOL_PREVIEW);
	const hiddenTools = agent.tools.length - TOOL_PREVIEW;

	return (
		<CanvasSurface
			viewport={viewport}
			layerRef={layerRef}
			label={`${agent.name} canvas. Drag or use arrow keys to pan; plus and minus to zoom.`}
			overlay={
				<>
					<TooltipIconButton
						label={panelOpen ? 'Hide run panel' : 'Show run panel'}
						side="right"
						variant="raised"
						aria-pressed={!panelOpen}
						className="absolute top-3 start-3 z-10 hidden @4xl/view:grid"
						onClick={onTogglePanel}
					>
						<PanelLeft
							aria-hidden="true"
							className={cn('size-3.5 transition-transform duration-(--duration-slow) ease-out', !panelOpen ? '-scale-x-100 rtl:scale-x-100' : 'rtl:-scale-x-100')}
						/>
					</TooltipIconButton>
					<CanvasZoomControls viewport={viewport} />
				</>
			}
		>
			<CanvasWires stages={state.nodes} layoutKey={`${nodes.key}|${moreTools}`} animate={!reducedMotion} />

			<div className="absolute top-0 flex flex-col gap-4" style={{ left: COLUMNS[0] }}>
				<CanvasNode {...node('schedule', 'Schedule', CalendarClock)}>
					<NodeCard>
						<NodeRow>
							<RowIcon icon={Clock} />
							<span>{agent.schedule.when}</span>
							<Dot />
							<span title={agent.schedule.label} className="truncate text-muted-foreground">
								{agent.schedule.label}
							</span>
						</NodeRow>
						<NodeRow>
							<RowIcon icon={Repeat} />
							<span className="font-mono text-xs">{agent.schedule.cron}</span>
							<Dot />
							<span className="text-muted-foreground">{agent.schedule.zone}</span>
						</NodeRow>
					</NodeCard>
				</CanvasNode>
				<CanvasNode {...node('triggers', 'Triggers', Zap, { tone: 'new', badge: <ToneBadge tone="primary">New</ToneBadge> })}>
					<NodeCard>
						<NodeRow>
							<IntegrationMark integration={integration(agent.trigger.integrationId)} size="xs" />
							<span title={agent.trigger.label} className="truncate">
								{agent.trigger.label}
							</span>
						</NodeRow>
						<NodeRow className="gap-1">
							{agent.trigger.conditions.map((condition, index) => (
								<React.Fragment key={condition}>
									{index > 0 ? <ToneBadge tone="neutral" className="h-[18px] px-1 text-[0.6875rem]">AND</ToneBadge> : null}
									<span className="font-mono text-xs">{condition}</span>
								</React.Fragment>
							))}
						</NodeRow>
					</NodeCard>
				</CanvasNode>
				<CanvasNode
					{...node('channels', 'Channels', MessagesSquare, {
						badge: (
							<ToneBadge tone="warning" onClick={() => emit({ type: 'set-identity', agentId: agent.id })}>
								<UserRound aria-hidden="true" />
								Set identity
							</ToneBadge>
						),
					})}
				>
					<NodeCard>
						<p className="px-2 py-1 text-xs leading-[18px] text-muted-foreground">{agent.channelsNotice}</p>
					</NodeCard>
				</CanvasNode>
				<CanvasNode {...node('memory', 'Memory', BookOpen, { meta: agent.memory.length, tone: 'new', badge: <ToneBadge tone="primary">New</ToneBadge> })}>
					<NodeCard>
						{agent.memory.map((memory) => (
							<NodeRow key={memory}>
								<RowIcon icon={FileText} />
								<span title={memory} className="truncate">
									{memory}
								</span>
							</NodeRow>
						))}
					</NodeCard>
				</CanvasNode>
			</div>

			<div className="absolute top-0 flex flex-col gap-4" style={{ left: COLUMNS[1] }}>
				<CanvasNode {...node('agent', 'Agent', Bot)}>
					<NodeCard className="gap-0.5 px-2.5 py-2">
						<p className="text-[0.8125rem] font-medium text-foreground">{agent.title}</p>
						<p className="text-xs leading-[18px] text-muted-foreground">{agent.tagline}</p>
					</NodeCard>
					<Instructions open={nodes.isOpen('instructions')} onToggle={() => nodes.toggle('instructions')} />
				</CanvasNode>
			</div>

			<div className="absolute top-0 flex flex-col gap-4" style={{ left: COLUMNS[2] }}>
				<CanvasNode
					{...node('tools', 'Tools', Wrench, { meta: agent.tools.length, stage: state.nodes.tools })}
					footer={
						hiddenTools > 0 ? (
							<button
								type="button"
								aria-expanded={moreTools}
								onClick={() => setMoreTools((value) => !value)}
								className={cn(
									'm-1 flex h-7 w-[calc(100%-8px)] cursor-pointer items-center gap-2 rounded-md px-1.5 text-start text-[0.8125rem] text-muted-foreground hover:bg-overlay-hover hover:text-foreground',
									focusRingClass,
								)}
							>
								<ChevronDown
									aria-hidden="true"
									className={cn('size-3.5 transition-transform duration-(--duration-moderate)', moreTools && 'rotate-180')}
								/>
								{moreTools ? 'Show less' : `Show ${hiddenTools} more`}
							</button>
						) : null
					}
				>
					<NodeCard>
						{tools.map((tool) => (
							<NodeRow key={tool.id}>
								<IntegrationMark integration={integration(tool.integrationId)} size="xs" />
								<span title={tool.label} className="truncate">
									{tool.label}
								</span>
							</NodeRow>
						))}
					</NodeCard>
				</CanvasNode>
				<CanvasNode {...node('subagents', 'Sub-agents', Workflow, { meta: agent.subagents.length, stage: state.nodes.subagents })}>
					<NodeCard>
						{agent.subagents.map((name) => (
							<NodeRow key={name}>
								<RowIcon icon={Bot} />
								<span title={name} className="truncate font-mono text-xs">
									{name}
								</span>
							</NodeRow>
						))}
					</NodeCard>
				</CanvasNode>
				<CanvasNode {...node('skills', 'Skills', Sparkles, { meta: agent.skills.length, stage: state.nodes.skills })}>
					<NodeCard>
						{agent.skills.map((name) => (
							<NodeRow key={name}>
								<RowIcon icon={Sparkles} />
								<span title={name} className="truncate">
									{name}
								</span>
							</NodeRow>
						))}
					</NodeCard>
				</CanvasNode>
			</div>
		</CanvasSurface>
	);
}

export { AgentCanvas };

'use client';

import { Bot, Check, ChevronRight, RotateCcw, Sparkles, Square, Zap } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { ApprovalCard } from '@/components/ui/ai/approval-card';
import { type AskChoice, AskCard } from '@/components/ui/ai/ask-card';
import { ChatContainer } from '@/components/ui/ai/chat-container';
import { CodeBlock } from '@/components/ui/ai/code-block';
import { FeedbackBar } from '@/components/ui/ai/feedback-bar';
import { iconEnterClass, MarkTile } from '@/components/ui/ai/mark-tile';
import { PlanTracker } from '@/components/ui/ai/plan-tracker';
import { Reasoning } from '@/components/ui/ai/reasoning';
import { Source, Sources } from '@/components/ui/ai/source';
import { ThinkingStatus } from '@/components/ui/ai/thinking-status';
import { ToolTrace } from '@/components/ui/ai/tool-trace';
import { Button } from '@/components/ui/button';
import { Spinner } from '@/components/ui/spinner';
import { type StatusSignal, StatusGlyph, StatusLabel } from '@/components/ui/agents-builder/agent-status';
import { useAgentsBuilder } from '@/components/ui/agents-builder/agents-builder-context';
import { Composer } from '@/components/ui/agents-builder/composer';
import { IntegrationMark } from '@/components/ui/agents-builder/integration-mark';
import { enterClass, focusRingClass, SurfaceBody, surfaceInsetClass, ToneBadge, TooltipIconButton, useInert } from '@/components/ui/workspace-kit/primitives';
import { useLatest } from '@/components/ui/workspace-kit/use-latest';
import { RevealText } from '@/components/ui/agents-builder/reveal-text';
import { usePlaybackClock } from '@/components/ui/agents-builder/playback';
import type { AgentRunScript, RunApproval, RunFailure, RunQuery, RunQuestion, ToolStep } from '@/components/ui/agents-builder/types';
import { type AgentRunState, RUN_TIMING, type RunGroupPlay, runProgress } from '@/components/ui/agents-builder/use-agent-run';

const GROUP_ICON = { subagents: <Bot />, skills: <Sparkles /> } as const;
const GROUP_NOUN = { subagents: ['agent', 'agents'], skills: ['skill', 'skills'] } as const;

/**
 * The line above a card a run stops on: the state's pixel mark, then the
 * sentence in the state's tone, the one coloured line on the card.
 */
function StatusLine({ signal, children }: { signal: StatusSignal; children: React.ReactNode }) {
	const { statusIndicator } = useAgentsBuilder();
	return (
		<StatusLabel indicator={statusIndicator} signal={signal} className="shrink-0">
			{children}
		</StatusLabel>
	);
}

// Static, so they are built once.
const APPROVAL_EYEBROW = <StatusLine signal="approval">Waiting for your approval</StatusLine>;
const QUESTION_EYEBROW = <StatusLine signal="input">Waiting for your answer</StatusLine>;
const QUEUED_EYEBROW = <StatusLine signal="queued">Queued</StatusLine>;

type RunGroupProps = {
	group: AgentRunScript['groups'][number];
	play: RunGroupPlay;
};

/** A fan-out group: streams its items open while running, then folds to a toggleable summary. */
function RunGroup({ group, play }: RunGroupProps) {
	const [expanded, setExpanded] = React.useState(false);
	const running = play.state === 'open';
	const open = running || expanded;
	const inertRef = useInert<HTMLUListElement>(!open);
	const [singular, plural] = GROUP_NOUN[group.id];
	const heading = (
		<>
			<span className="min-w-0 text-foreground [overflow-wrap:anywhere]">{group.label}</span>
			<span className="shrink-0 text-muted-foreground tabular-nums">
				· {group.items.length} {group.items.length === 1 ? singular : plural}
			</span>
		</>
	);
	const row = 'flex min-h-8 w-full items-center gap-1.5 px-2 py-1 text-start text-[0.8125rem]';

	return (
		<li className={enterClass}>
			{running ? (
				<div className={row}>
					<Spinner aria-hidden="true" role={undefined} className="size-3.5 text-muted-foreground" strokeWidth={1.5} />
					{heading}
				</div>
			) : (
				<button
					type="button"
					aria-expanded={open}
					onClick={() => setExpanded((value) => !value)}
					className={cn(row, 'cursor-pointer hover:bg-overlay-hover', focusRingClass, 'focus-visible:ring-inset')}
				>
					<ChevronRight
						aria-hidden="true"
						className={cn(
							'size-3.5 shrink-0 text-muted-foreground transition-transform duration-(--duration-moderate) ease-out motion-reduce:transition-none',
							open ? 'rotate-90' : 'rtl:-scale-x-100',
						)}
					/>
					{heading}
				</button>
			)}
			<div
				className={cn(
					'grid transition-[grid-template-rows] duration-(--duration-slow) ease-(--ease-out) motion-reduce:transition-none',
					open ? 'grid-rows-[1fr]' : 'grid-rows-[0fr]',
				)}
			>
				<ul ref={inertRef} className="min-h-0 overflow-hidden">
					{group.items.slice(0, play.shown).map((item, index) => (
						<li key={item} className={cn('flex h-7 items-center gap-2 pe-2 ps-[26px] text-[0.8125rem] text-muted-foreground', enterClass)}>
							<MarkTile>{GROUP_ICON[group.id]}</MarkTile>
							<span title={item} className="min-w-0 flex-1 truncate">
								{item}
							</span>
							{index < play.done ? <Check aria-label="Done" className={cn('size-3 text-subtle-foreground', iconEnterClass)} /> : null}
						</li>
					))}
				</ul>
			</div>
		</li>
	);
}

function cellTone(cell: string) {
	if (cell.startsWith('+')) return 'text-success-foreground';
	if (cell.startsWith('−') || cell.startsWith('-')) return 'text-destructive';
	return undefined;
}

/** Query result: numeric columns right-aligned, gains and losses tinted, caption in a footer strip. */
function ResultTable({ query }: { query: RunQuery }) {
	return (
		<figure className={cn(surfaceInsetClass, 'rounded-lg bg-card shadow-card', enterClass)}>
			<SurfaceBody>
				<div className="overflow-x-auto">
					<table className="w-full text-[0.8125rem] tabular-nums">
						<thead>
							<tr className="border-b border-dashed border-foreground/10 text-start text-xs text-muted-foreground">
								{query.columns.map((column, index) => (
									<th key={column} scope="col" className={cn('h-8 px-3 font-medium whitespace-nowrap', index > 0 && 'text-end')}>
										{column}
									</th>
								))}
							</tr>
						</thead>
						<tbody>
							{query.rows.map((row) => (
								<tr key={row.join()} className="h-8">
									{row.map((cell, index) =>
										index === 0 ? (
											<th key={index} scope="row" className="px-3 text-start font-normal text-foreground">
												{cell}
											</th>
										) : (
											<td key={index} className={cn('px-3 text-end text-foreground', cellTone(cell))}>
												{cell}
											</td>
										),
									)}
								</tr>
							))}
						</tbody>
					</table>
				</div>
				{query.caption ? (
					<figcaption className="border-t border-dashed border-foreground/10 bg-muted/60 px-3 py-1.5 text-xs text-muted-foreground tabular-nums">
						{query.caption}
					</figcaption>
				) : null}
			</SurfaceBody>
		</figure>
	);
}

type Decision = 'approved' | 'skipped' | null;

/** Chosen option ids by question id, `'skipped'`, or `null` while unanswered. */
type Answer = Record<string, string[]> | 'skipped' | null;

/**
 * Plays a gate's tool calls one by one once `active`, then reports whether
 * they finished. `settled` starts with every call done, for a past run.
 */
function useGateSteps(steps: ToolStep[], active: boolean, settled: boolean) {
	const [done, setDone] = React.useState(settled ? steps.length : 0);
	const running = active && done < steps.length;
	usePlaybackClock(running ? { delay: done === 0 ? RUN_TIMING.stepsSpin : RUN_TIMING.stepWork } : undefined, false, () =>
		setDone((value) => value + 1),
	);
	return { done, finished: done >= steps.length };
}

/** A gate's follow-up tool calls as a live trace, then the agent's reply once they finish. */
function GateOutcome({ steps, done, reply }: { steps: ToolStep[] | null; done: number; reply: string }) {
	const { integration } = useAgentsBuilder();
	return (
		<>
			{steps ? (
				<ToolTrace
					title="Write tools"
					steps={steps.map((step, index) => ({
						id: step.id,
						label: step.label,
						icon: <IntegrationMark integration={integration(step.integrationId)} bare />,
						status: index < done ? 'done' : index === done ? 'running' : 'pending',
					}))}
				/>
			) : null}
			{!steps || done >= steps.length ? (
				<RevealText text={reply} revealing duration={reply.length * RUN_TIMING.charMs} className="leading-[22px] text-foreground" />
			) : null}
		</>
	);
}

function ApprovalBlock({ approval, decision, done, onDecide }: { approval: RunApproval; decision: Decision; done: number; onDecide: (approved: boolean) => void }) {
	if (!decision) {
		return (
			<ApprovalCard
				className={cn('max-w-none rounded-xl', enterClass)}
				eyebrow={APPROVAL_EYEBROW}
				title={approval.title}
				description={approval.description}
				preview={<p className="rounded-md bg-muted/60 px-2.5 py-2 text-[0.8125rem] leading-5 text-pretty text-foreground [overflow-wrap:anywhere]">{approval.preview}</p>}
				confirmLabel={approval.confirmLabel}
				skipLabel={approval.skipLabel}
				onConfirm={() => onDecide(true)}
				onSkip={() => onDecide(false)}
			/>
		);
	}
	const approved = decision === 'approved';
	return (
		<div className="flex flex-col gap-3">
			<p className={cn('flex min-h-6 items-center gap-1.5 text-[0.8125rem] text-muted-foreground [overflow-wrap:anywhere]', enterClass)}>
				<Check aria-hidden="true" className={cn('size-3.5 shrink-0', iconEnterClass)} />
				<span className="min-w-0">{approved ? `You approved: ${approval.confirmLabel}` : `You chose: ${approval.skipLabel}`}</span>
			</p>
			<GateOutcome steps={approved ? approval.steps : null} done={done} reply={approved ? approval.approvedText : approval.skippedText} />
		</div>
	);
}

function answerIds(choice: AskChoice) {
	return 'option' in choice ? [choice.option] : [choice.other];
}

/** The question that ends a run: the ask card, then its summary, the follow-up calls, and the agent's reply. */
function QuestionBlock({
	question,
	answer,
	done,
	onAnswer,
}: {
	question: RunQuestion;
	answer: Answer;
	done: number;
	onAnswer: (answer: Exclude<Answer, null>) => void;
}) {
	const questions = question.questions.map((item) => ({
		id: item.id,
		question: item.question,
		options: item.options.map((option) => ({ id: option.id, label: option.label })),
		allowOther: false,
	}));
	if (answer === null) {
		return (
			<AskCard
				className={cn('max-w-none', enterClass)}
				eyebrow={QUESTION_EYEBROW}
				icon={null}
				questions={questions}
				onSubmit={(choices) => onAnswer(Object.fromEntries(Object.entries(choices).map(([id, choice]) => [id, answerIds(choice)])))}
				onSkip={() => onAnswer('skipped')}
			/>
		);
	}
	if (answer === 'skipped') {
		return (
			<div className="flex flex-col gap-3">
				<AskCard className="max-w-none" questions={questions} answer={{ skipped: true }} />
				<GateOutcome steps={null} done={0} reply={question.skippedText} />
			</div>
		);
	}
	// Each chosen option adds its own sentence; with none written, the generic reply stands in.
	const replies = question.questions.flatMap((item) => item.options.filter((option) => answer[item.id]?.includes(option.id) && option.reply).map((option) => option.reply!));
	const reply = replies.length ? replies.join(' ') : question.answeredText;
	return (
		<div className="flex flex-col gap-3">
			<AskCard
				className="max-w-none"
				questions={questions}
				answer={{ choices: Object.fromEntries(Object.entries(answer).map(([id, [option = '']]) => [id, { option }])) }}
			/>
			<GateOutcome steps={question.steps} done={done} reply={reply} />
		</div>
	);
}

/**
 * The card a run stops on when it cannot go on by itself: a status line, a
 * title, the body, and its actions on the right, like the approval and
 * question cards.
 */
function StopCard({
	eyebrow,
	title,
	actions,
	children,
}: {
	eyebrow: React.ReactNode;
	title: React.ReactNode;
	actions: React.ReactNode;
	children?: React.ReactNode;
}) {
	return (
		<div className={cn('flex flex-col gap-3 rounded-xl bg-card p-3 shadow-card', enterClass)}>
			<div className="flex flex-col gap-1.5">
				<p className="flex min-h-4 min-w-0 items-center gap-1.5 text-xs text-muted-foreground [&_svg]:size-3.5 [&_svg]:shrink-0">{eyebrow}</p>
				<p className="text-sm font-medium text-pretty text-foreground [overflow-wrap:anywhere]">{title}</p>
			</div>
			{children}
			<div className="flex flex-wrap items-center justify-end gap-1.5">{actions}</div>
		</div>
	);
}

/** Where a failed run stopped: the call that failed, the error, its raw output, and a retry. */
function FailureBlock({ failure, step, onRetry }: { failure: RunFailure; step?: ToolStep; onRetry?: () => void }) {
	return (
		<StopCard
			eyebrow={
				<>
					<StatusLine signal="failed">{step ? 'Failed at' : 'Run failed'}</StatusLine>
					{step ? <span className="min-w-0 truncate">{step.label}</span> : null}
				</>
			}
			title={failure.message}
			actions={
				<Button size="sm" onClick={onRetry}>
					<RotateCcw aria-hidden="true" />
					{failure.retryLabel ?? 'Retry run'}
				</Button>
			}
		>
			{failure.log ? <CodeBlock code={failure.log} filename="Output" highlight={false} maxCollapsedLines={false} /> : null}
		</StopCard>
	);
}

/** A run waiting for its slot: when it starts, the plan it will follow, and a way to start it now. */
function QueuedBlock({ note, plan, onStart }: { note?: string; plan?: string[]; onStart?: () => void }) {
	return (
		<StopCard
			eyebrow={QUEUED_EYEBROW}
			title={note ?? 'Starts at its next scheduled time.'}
			actions={
				<Button size="sm" onClick={onStart}>
					Run now
				</Button>
			}
		>
			{plan?.length ? (
				<div className="flex flex-col gap-1">
					<p className="text-xs text-muted-foreground">Up next</p>
					{/* Hung from a rail like the tool trace's, dashed because none of it has run yet, with each number zero-padded. */}
					<ol className="ms-2 flex flex-col border-s border-dashed border-subtle-foreground/35">
						{plan.map((step, index) => (
							<li key={step} className="flex min-h-7 items-center gap-2 ps-3 text-[0.8125rem] text-muted-foreground">
								<span aria-hidden="true" className="shrink-0 font-mono text-[0.6875rem] text-subtle-foreground tabular-nums">
									{String(index + 1).padStart(2, '0')}
								</span>
								<span className="min-w-0 [overflow-wrap:anywhere]">{step}</span>
							</li>
						))}
					</ol>
				</div>
			) : null}
		</StopCard>
	);
}

function CommandBar({ script, phase, progress, onStop }: { script: AgentRunScript; phase: RunPhase; progress?: number; onStop: () => void }) {
	const { statusIndicator } = useAgentsBuilder();
	return (
		<div className="relative z-10 flex h-[50px] shrink-0 items-center gap-3 rounded-xl bg-card px-3 shadow-card">
			<p title={`${script.command.verb} ${script.command.skill} ${script.command.scope}`} className="flex min-w-0 flex-1 items-center gap-1.5 text-sm whitespace-nowrap text-foreground">
				{script.command.verb}
				{/* The skill chip shrinks and truncates, so a long skill name cannot print over the status badge. */}
				<ToneBadge tone="primary" className="min-w-0 shrink">
					<Zap aria-hidden="true" className="shrink-0" />
					<span title={script.command.skill} className="truncate">{script.command.skill}</span>
				</ToneBadge>
				<span title={script.command.scope} className="truncate">{script.command.scope}</span>
			</p>
			{phase === 'running' ? (
				<span className="flex shrink-0 items-center gap-2.5">
					<StatusGlyph indicator={statusIndicator} signal="running" progress={progress} />
					<TooltipIconButton
						label="Stop run"
						size="sm"
						className="bg-foreground text-background hover:bg-foreground/90 hover:text-background"
						onClick={onStop}
					>
						<Square aria-hidden="true" className="size-2.5 fill-current" />
					</TooltipIconButton>
				</span>
			) : (
				<StatusLabel indicator={statusIndicator} signal={phase} progress={progress} className="shrink-0 text-xs">
					{RUN_PHASE_WORD[phase]}
				</StatusLabel>
			)}
		</div>
	);
}

/** Where the run stands, as the sidebar roster shows it. */
type RunPhase = 'queued' | 'running' | 'approval' | 'input' | 'failed' | 'done';

/** The header tag's word once the run stops. Both waits read the same here; the card below says which. */
const RUN_PHASE_WORD = { queued: 'Queued', approval: 'Needs you', input: 'Needs you', failed: 'Failed', done: 'Done' } as const;

type AgentRunPanelProps = {
	script: AgentRunScript;
	state: AgentRunState;
	onStop: () => void;
	/** Called whenever the run starts waiting on a person, resumes, or completes. */
	onPhaseChange?: (phase: RunPhase) => void;
	/** Brings the decision or the failure into view and focus once it shows, e.g. when the agent opened to decide. */
	focusStop?: boolean;
	/** A past run: its approval or question shows as already settled, with every follow-up call done. */
	resolved?: boolean;
	/** Holds the run before it starts; the panel offers "Run now". */
	queued?: boolean;
	/** When a queued run starts, e.g. "Starts at 09:00 UTC." */
	queuedNote?: string;
	onStart?: () => void;
	onRetry?: () => void;
};

/**
 * The current run, narrated: command bar, streamed notes, the tool trace,
 * sub-agent and skill fan-out, live thinking status, and a follow-up composer.
 */
function AgentRunPanel({
	script,
	state,
	onStop,
	onPhaseChange,
	focusStop = false,
	resolved = false,
	queued = false,
	queuedNote,
	onStart,
	onRetry,
}: AgentRunPanelProps) {
	const { integration, emit, currentAgent, statusIndicator } = useAgentsBuilder();
	const agentId = currentAgent.agent.id;
	const [followUps, setFollowUps] = React.useState<string[]>([]);
	// A past run settled its gate long ago: approved, or answered with the first options.
	const [decision, setDecision] = React.useState<Decision>(resolved && script.approval ? 'approved' : null);
	const [answer, setAnswer] = React.useState<Answer>(() =>
		resolved && script.question && !script.approval
			? Object.fromEntries(script.question.questions.map((item) => [item.id, item.options[0] ? [item.options[0].id] : []]))
			: null,
	);
	const approvedSteps = useGateSteps(script.approval?.steps ?? [], decision === 'approved', resolved);
	const answeredSteps = useGateSteps(script.question?.steps ?? [], answer !== null && answer !== 'skipped', resolved);
	const startedGroups = script.groups.filter((group) => state[group.id].state !== 'waiting');
	const failed = state.failedStep !== null;
	const awaitingApproval = Boolean(script.approval) && state.approval && !decision;
	const awaitingAnswer = Boolean(script.question) && state.question && answer === null;
	const gateFinished = script.approval
		? decision === 'skipped' || (decision === 'approved' && approvedSteps.finished)
		: script.question
			? answer === 'skipped' || (answer !== null && answeredSteps.finished)
			: true;
	const complete = state.settled && !failed && gateFinished;
	const phase: RunPhase = queued
		? 'queued'
		: failed
			? 'failed'
			: complete
				? 'done'
				: awaitingApproval
					? 'approval'
					: awaitingAnswer
						? 'input'
						: 'running';
	const stopped = phase === 'approval' || phase === 'input' || phase === 'failed';
	const onPhaseChangeRef = useLatest(onPhaseChange);
	const stopRef = React.useRef<HTMLDivElement>(null);
	const stopFocused = React.useRef(false);

	React.useEffect(() => onPhaseChangeRef.current?.(phase), [onPhaseChangeRef, phase]);

	React.useEffect(() => {
		// Only the first time the run stops; afterwards focus stays where the person put it.
		if (!focusStop || !stopped || stopFocused.current) return;
		stopFocused.current = true;
		stopRef.current?.scrollIntoView({ block: 'center' });
		stopRef.current?.focus({ preventScroll: true });
	}, [focusStop, stopped]);
	const plan = script.plan && {
		steps: script.plan.map((label, index) => {
			const done = index < state.planDone || (complete && index === script.plan!.length - 1);
			return { label, status: done ? ('done' as const) : index === state.planDone ? ('in_progress' as const) : ('pending' as const) };
		}),
	};

	return (
		<aside aria-label="Current run" className="flex h-full w-full shrink-0 flex-col p-3 pb-[max(0.75rem,env(safe-area-inset-bottom))] @4xl/view:w-[395px] @4xl/view:pe-0">
			<div className="group/run relative flex min-h-0 flex-1 flex-col">
				<CommandBar
					script={script}
					phase={phase}
					progress={runProgress(script, state)}
					onStop={() => {
						onStop();
						emit({ type: 'stop-run' });
					}}
				/>
				<div
					aria-hidden="true"
					className="pointer-events-none absolute inset-x-0 top-0 z-[5] h-[70px] bg-gradient-to-b from-background via-background via-60% to-transparent"
				/>
				<ChatContainer className="-mt-2.5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
					<div className="flex flex-col gap-5 pt-6 pb-10">
						{plan && !queued ? <PlanTracker plan={plan} streaming={!complete} flushBottom={false} className="px-3" /> : null}
						{script.reasoning && state.reasoning !== 'hidden' ? (
							<Reasoning
								className="-my-2 px-1.5"
								content={script.reasoning.text}
								isStreaming={state.reasoning === 'streaming'}
								durationMs={state.reasoning === 'done' ? script.reasoning.seconds * 1000 : null}
							/>
						) : null}
						{script.paragraphs.slice(0, state.shownParagraphs).map((paragraph, index) => (
							<RevealText
								key={paragraph}
								text={paragraph}
								revealing={state.typing === index}
								duration={paragraph.length * RUN_TIMING.charMs}
								className="px-3 leading-[22px] text-muted-foreground"
							/>
						))}
						{state.shownSteps > 0 ? (
							<ToolTrace
								className="px-3"
								// Calls after a failure never ran, so they are not listed.
								steps={script.steps.slice(0, failed ? state.failedStep! + 1 : undefined).map((step, index) => ({
									id: step.id,
									label: step.label,
									icon: <IntegrationMark integration={integration(step.integrationId)} bare />,
									status:
										index === state.failedStep ? 'error' : index < state.doneSteps ? 'done' : index === state.doneSteps ? 'running' : 'pending',
								}))}
							/>
						) : null}
						{script.query && state.query !== 'hidden' ? (
							<div className={cn('flex flex-col gap-2 px-3', enterClass)}>
								<CodeBlock
									code={script.query.sql}
									language="sql"
									filename={script.query.name}
									streamingLines={state.query === 'code'}
									lineIntervalMs={110}
									className="bg-card"
								/>
								{state.query === 'rows' ? <ResultTable query={script.query} /> : null}
							</div>
						) : null}
						{startedGroups.length > 0 ? (
							<ul className="mx-3 divide-y divide-border overflow-hidden rounded-xl bg-card shadow-card">
								{startedGroups.map((group) => (
									<RunGroup key={group.id} group={group} play={state[group.id]} />
								))}
							</ul>
						) : null}
						{script.findings?.paragraphs.slice(0, state.shownFindings).map((paragraph, index) => (
							<RevealText
								key={paragraph}
								text={paragraph}
								revealing={state.typingFinding === index}
								duration={paragraph.length * RUN_TIMING.charMs}
								className="px-3 leading-[22px] text-foreground"
							/>
						))}
						{script.findings && state.sources ? (
							<Sources label="Sources" className={cn('px-3', enterClass)}>
								{script.findings.sources.map((source) => (
									<Source key={source.title} title={source.title} description={source.description} />
								))}
							</Sources>
						) : null}
						{script.approval && state.approval ? (
							<div ref={stopRef} tabIndex={-1} role="group" aria-label={script.approval.title} className="px-3 outline-none">
								<ApprovalBlock
									approval={script.approval}
									decision={decision}
									done={approvedSteps.done}
									onDecide={(approved) => {
										setDecision(approved ? 'approved' : 'skipped');
										emit({ type: 'approve-run', agentId, approved });
									}}
								/>
							</div>
						) : null}
						{script.question && !script.approval && state.question ? (
							<div ref={stopRef} tabIndex={-1} role="group" aria-label={script.question.title} className="px-3 outline-none">
								<QuestionBlock
									question={script.question}
									answer={answer}
									done={answeredSteps.done}
									onAnswer={(next) => {
										setAnswer(next);
										emit({ type: 'answer-run', agentId, answers: next === 'skipped' ? null : next });
									}}
								/>
							</div>
						) : null}
						{failed && script.failure ? (
							<div ref={stopRef} tabIndex={-1} role="group" aria-label="Run failed" className="px-3 outline-none">
								<FailureBlock failure={script.failure} step={script.steps.find((step) => step.id === script.failure?.stepId)} onRetry={onRetry} />
							</div>
						) : null}
						{queued ? (
							<div className="px-3">
								<QueuedBlock note={queuedNote} plan={script.plan} onStart={onStart} />
							</div>
						) : null}
						{followUps.map((text, index) => (
							<div key={index} className={cn('mx-3 rounded-xl bg-card px-3 py-2 text-sm whitespace-pre-wrap text-foreground shadow-card [overflow-wrap:anywhere]', enterClass)}>
								{text}
							</div>
						))}
						{complete ? (
							<div className={cn('flex items-center justify-between gap-2 px-3', enterClass)}>
								<p className="flex h-7 items-center gap-2 text-[0.8125rem] text-muted-foreground">
									<StatusGlyph indicator={statusIndicator} signal="done" />
									Run complete
								</p>
								<FeedbackBar showRegenerate={false} copyText={script.findings?.paragraphs.join('\n\n')} />
							</div>
						) : state.settled || queued || awaitingApproval || awaitingAnswer ? null : (
							<ThinkingStatus
								className="px-3"
								elapsedSeconds={script.thinking.seconds}
								tokens={script.thinking.tokens}
								tokensPerTick={35}
							/>
						)}
					</div>
				</ChatContainer>
				<div
					aria-hidden="true"
					className="pointer-events-none absolute inset-x-0 bottom-0 z-[5] h-10 bg-gradient-to-t from-background to-transparent opacity-0 transition-opacity duration-(--duration-moderate) group-has-[[data-at-bottom=false]]/run:opacity-100"
				/>
			</div>
			<Composer
				surface="run"
				ariaLabel="Add a follow-up"
				placeholder="Add a follow-up"
				onSubmit={(text) => {
					setFollowUps((current) => [...current, text]);
					emit({ type: 'send-follow-up', surface: 'run', text });
				}}
			/>
		</aside>
	);
}

export { AgentRunPanel };
export type { AgentRunPanelProps, RunPhase };

'use client';

import * as React from 'react';

import { cn } from '@/lib/utils';
import type { AgentStatus, AgentStatusIndicator, AgentSummary } from '@/components/ui/agents-builder/types';

/** Resolves the deprecated `running` flag into a status. */
function agentStatus(agent: AgentSummary): AgentStatus {
	return agent.status ?? (agent.running ? 'running' : 'idle');
}

/** A run is still open: running, or paused on a person. These names shimmer. */
function isInFlight(status: AgentStatus) {
	return status === 'running' || status === 'approval' || status === 'input';
}

/** Paused on a person: opening the agent jumps straight to the decision. */
function isWaitingOnYou(status: StatusSignal) {
	return status === 'approval' || status === 'input';
}

/** Kept on screen even past the roster limit. */
function needsAttention(status: AgentStatus) {
	return isWaitingOnYou(status) || status === 'failed';
}

const STATUS_PHRASE: Record<AgentStatus, string | null> = {
	idle: null,
	queued: 'Queued',
	running: 'Running',
	approval: 'Waiting for your approval',
	input: 'Waiting for your answer',
	failed: 'Last run failed',
};

/** Sentence-case state for tooltips; `null` for an idle agent with nothing new. */
function statusPhrase(agent: AgentSummary): string | null {
	const status = agentStatus(agent);
	return STATUS_PHRASE[status] ?? (agent.unread ? 'New result' : null);
}

/** Accessible name: "Revenue Analyst, waiting for your approval". */
function agentLabel(agent: AgentSummary) {
	const phrase = statusPhrase(agent);
	return phrase ? `${agent.name}, ${phrase.toLowerCase()}` : agent.name;
}

const TAG_WORD = { approval: 'Approve', input: 'Answer', failed: 'Failed', queued: 'Queued' } as const;
type TaggedStatus = keyof typeof TAG_WORD;

/** States that show a word at the end of the row: the three that need you, and a queued run. */
function hasStatusTag(status: AgentStatus): status is TaggedStatus {
	return status in TAG_WORD;
}

/** A state an indicator draws: an agent's status, or a finished run whose result waits to be read. */
type StatusSignal = AgentStatus | 'done';

/**
 * What an indicator draws for anything that runs, such as an agent or a coding session: its status, or `done` while
 * the result of a finished run is unread.
 */
function statusSignal({ status = 'idle', unread }: { status?: StatusSignal; unread?: boolean }): StatusSignal {
	return status === 'idle' && unread ? 'done' : status;
}

/** What the roster draws for an agent: its status, or `done` while a fresh result is unread. */
function agentSignal(agent: AgentSummary): StatusSignal {
	return statusSignal({ status: agentStatus(agent), unread: agent.unread });
}

/** Colour belongs to the states that need you; everything else stays grey. */
const SIGNAL_TONE: Partial<Record<StatusSignal, string>> = {
	approval: 'var(--warning)',
	input: 'var(--primary)',
	failed: 'var(--destructive)',
};

/** Sets `--tone` for a toned state; calm states set nothing. */
function toneStyle(signal: StatusSignal): React.CSSProperties | undefined {
	const tone = SIGNAL_TONE[signal];
	return tone ? ({ '--tone': tone } as React.CSSProperties) : undefined;
}

/** Text in the state's tone, mixed toward the text colour so it holds contrast in both themes. */
const toneTextClass = 'text-[color-mix(in_oklab,var(--tone),var(--foreground)_28%)]';

const RAIL_PLACEMENT = {
	// Centred on a project's rail line: the list's 1px border, then 6px of padding before the row, so
	// the line's centre is 6.5px before the row and a 2px bar starts 7.5px before it, overhanging the
	// line by half a pixel each side. It reaches 1px past each end, half the 2px gap between rows, so
	// neighbouring stretches meet.
	rail: 'absolute -inset-y-px -start-[7.5px] w-0.5',
	edge: 'absolute inset-y-1.5 start-0 w-0.5',
	inline: 'relative h-3.5 w-0.5 shrink-0',
	// A slim capsule 3px before the box it sits beside, centred on it. Every state draws the same size.
	pill: 'absolute top-1/2 -start-[5px] h-5 w-0.5 -translate-y-1/2',
} as const;

type SignalRailProps = {
	signal: StatusSignal;
	/**
	 * `rail` lies on the line a project's rows hang from; `edge` draws at the
	 * row's own start edge where no line runs; `inline` is a short bar beside
	 * text, as in a status line; `pill` is a capsule beside a square, as in
	 * the icon rail.
	 */
	placement?: keyof typeof RAIL_PLACEMENT;
	className?: string;
};

/**
 * A stretch of rail as a status channel. While a run goes a light travels
 * down it; waiting on you it becomes a bar in the state's tone that breathes;
 * a failure holds the bar still; a queued run is dashed. An idle agent, or one
 * whose run has finished, draws nothing and leaves the rail as it is.
 */
function SignalRail({ signal, placement = 'rail', className }: SignalRailProps) {
	if (signal === 'idle' || signal === 'done') return null;
	if (placement === 'pill') {
		return (
			<span aria-hidden="true" data-slot="signal-rail" data-signal={signal} style={toneStyle(signal)} className={cn(RAIL_PLACEMENT.pill, className)}>
				<span
					className={cn(
						'absolute inset-0 rounded-full',
						signal === 'running'
							? 'bg-muted-foreground animate-[agent-pill-breathe_1.6s_ease-in-out_infinite] motion-reduce:animate-none'
							: signal === 'queued'
								? 'bg-[repeating-linear-gradient(to_bottom,var(--subtle-foreground)_0_2px,transparent_2px_4px)]'
								: cn('bg-(--tone)', signal !== 'failed' && 'animate-pulse motion-reduce:animate-none'),
					)}
				/>
			</span>
		);
	}
	return (
		<span aria-hidden="true" data-slot="signal-rail" data-signal={signal} style={toneStyle(signal)} className={cn(RAIL_PLACEMENT[placement], className)}>
			{signal === 'running' ? (
				// On the rail the project's own line is the track, so only the light is drawn over it.
				<span
					className={cn(
						'absolute inset-y-0 left-1/2 w-px -translate-x-1/2 overflow-hidden',
						placement !== 'rail' && 'bg-[color-mix(in_oklab,var(--foreground)_14%,transparent)]',
					)}
				>
					<span className="absolute inset-x-0 h-4 bg-[linear-gradient(to_bottom,transparent,var(--foreground),transparent)] animate-[agent-rail-travel_1.6s_cubic-bezier(0.45,0,0.55,1)_infinite] motion-reduce:top-1/2 motion-reduce:h-1 motion-reduce:animate-none" />
				</span>
			) : signal === 'queued' ? (
				// On the rail the gaps take the sidebar's colour so they cut its line; elsewhere they are clear.
				<span
					className={cn(
						'absolute inset-y-0 left-1/2 w-px -translate-x-1/2 bg-[repeating-linear-gradient(to_bottom,var(--subtle-foreground)_0_2px,var(--rail-gap)_2px_5px)]',
						placement === 'rail' ? '[--rail-gap:var(--sidebar)]' : '[--rail-gap:transparent]',
					)}
				/>
			) : (
				<span
					className={cn(
						// On the rail the bar fills its stretch with square ends, so it joins the line and its neighbours without a seam.
						'absolute inset-0',
						placement === 'rail' ? 'rounded-none' : 'rounded-full',
						'bg-(--tone) shadow-[0_0_6px_color-mix(in_oklab,var(--tone)_45%,transparent)]',
						signal !== 'failed' && 'animate-pulse motion-reduce:animate-none',
					)}
				/>
			)}
		</span>
	);
}

const RING_SIZE = {
	sm: { box: 14, r: 5.25, className: 'size-3.5' },
	lg: { box: 24, r: 11, className: 'size-6' },
} as const;

type AgentRingProps = {
	signal: StatusSignal;
	/** How far the run got, from 0 to 1. Without it a stop closes the ring and a run only spins. */
	progress?: number;
	/** `sm`: a 14px glyph before a name. `lg`: a 24px ring round the initials in the icon rail. */
	size?: keyof typeof RING_SIZE;
	/** Drawn inside an `lg` ring, e.g. the initials. */
	children?: React.ReactNode;
	className?: string;
};

/**
 * One drawn circle for every state, and its arc is how far the run got. A
 * running ring spins a short highlight over the arc; a stop holds the arc in
 * its tone with a centre dot, breathing while it waits on you; queued is a
 * dashed ring; a fresh result closes the ring round a check; idle is the
 * empty track.
 */
function AgentRing({ signal, progress, size = 'sm', children, className }: AgentRingProps) {
	const { box, r, className: sizeClass } = RING_SIZE[size];
	const length = 2 * Math.PI * r;
	const stopped = signal === 'approval' || signal === 'input' || signal === 'failed';
	const arc = signal === 'done' ? 1 : signal === 'running' || stopped ? Math.min(progress ?? (stopped ? 1 : 0), 1) : 0;
	const circle = { cx: box / 2, cy: box / 2, r, fill: 'none', stroke: 'currentColor', strokeWidth: 1.5 } as const;
	return (
		<span
			aria-hidden="true"
			data-slot="agent-ring"
			data-signal={signal}
			style={toneStyle(signal)}
			className={cn(
				'relative grid shrink-0 place-items-center',
				sizeClass,
				SIGNAL_TONE[signal] ? 'text-(--tone)' : signal === 'idle' ? 'text-subtle-foreground' : signal === 'done' ? 'text-foreground' : 'text-muted-foreground',
				className,
			)}
		>
			<svg viewBox={`0 0 ${box} ${box}`} className="absolute inset-0 size-full -rotate-90">
				<circle {...circle} strokeDasharray={signal === 'queued' ? '1.6 2' : undefined} opacity={signal === 'queued' ? 0.7 : 0.22} />
				{arc > 0 ? (
					<circle
						{...circle}
						strokeLinecap="round"
						strokeDasharray={`${length * arc} ${length}`}
						className="transition-[stroke-dasharray] duration-(--duration-slow) ease-(--ease-out) motion-reduce:transition-none"
					/>
				) : null}
			</svg>
			{signal === 'running' ? (
				<svg viewBox={`0 0 ${box} ${box}`} className="absolute inset-0 size-full animate-spin text-foreground [animation-duration:1.2s] motion-reduce:hidden">
					<circle {...circle} strokeLinecap="round" strokeDasharray={`${length * 0.14} ${length}`} />
				</svg>
			) : null}
			{size === 'lg' ? (
				children
			) : stopped ? (
				<span className={cn('size-1 rounded-full bg-current', signal !== 'failed' && 'animate-pulse motion-reduce:animate-none')} />
			) : signal === 'done' ? (
				<svg viewBox="0 0 14 14" className="absolute inset-0 size-full">
					<path d="M4.6 7.2 6.3 8.9 9.5 5.5" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
				</svg>
			) : null}
		</span>
	);
}

type StatusLabelProps = Omit<React.ComponentProps<'span'>, 'children'> & {
	indicator: AgentStatusIndicator;
	signal: StatusSignal;
	progress?: number;
	children: React.ReactNode;
};

/** A state's glyph in the chosen indicator: a ring, or a short bar of rail. */
function StatusGlyph({ indicator, signal, progress }: Pick<StatusLabelProps, 'indicator' | 'signal' | 'progress'>) {
	return indicator === 'rings' ? <AgentRing signal={signal} progress={progress} /> : <SignalRail signal={signal} placement="inline" />;
}

/** A state's glyph in the chosen indicator, then its words, in the state's tone when it needs you. */
function StatusLabel({ indicator, signal, progress, children, className, style, ...props }: StatusLabelProps) {
	return (
		<span
			{...props}
			style={{ ...toneStyle(signal), ...style }}
			className={cn('inline-flex min-w-0 items-center gap-1.5 font-medium', SIGNAL_TONE[signal] ? toneTextClass : 'text-muted-foreground', className)}
		>
			<StatusGlyph indicator={indicator} signal={signal} progress={progress} />
			<span className="truncate">{children}</span>
		</span>
	);
}

/**
 * The tag word on its own, under the initials in the icon rail, in the
 * state's tone. It shimmers while the run waits on you, like the initials
 * above it, and holds still once the run has failed or while it is queued.
 */
function AgentStatusWord({ status }: { status: AgentStatus }) {
	if (!hasStatusTag(status)) return null;
	return (
		<span
			aria-hidden="true"
			style={toneStyle(status)}
			className={cn(
				'block text-[0.5625rem] leading-none font-medium tracking-tight whitespace-nowrap',
				status === 'queued' ? '[--word:var(--subtle-foreground)]' : '[--word:color-mix(in_oklab,var(--tone),var(--foreground)_28%)]',
				isWaitingOnYou(status)
					? [
							// Same sweep as TextShimmer: toward the page colour in light, toward the text colour in dark.
							'bg-[linear-gradient(90deg,var(--word)_35%,color-mix(in_oklab,var(--word),var(--sidebar)_55%)_50%,var(--word)_65%)]',
							'dark:bg-[linear-gradient(90deg,var(--word)_35%,var(--foreground)_50%,var(--word)_65%)]',
							'bg-size-[200%_100%] bg-clip-text text-transparent animate-[ai-shimmer-text_1.4s_linear_infinite]',
							'motion-reduce:animate-none motion-reduce:bg-none motion-reduce:text-(--word)',
						]
					: 'text-(--word)',
			)}
		>
			{TAG_WORD[status]}
		</span>
	);
}

/** Most pressing first: a decision, then a question, then a failure, then a queued run. */
const TAG_PRIORITY: TaggedStatus[] = ['approval', 'input', 'failed', 'queued'];

/** The tag a folded group of agents shows: its most pressing agent's, or `null` when none has one. */
function mostUrgentTag(agents: AgentSummary[]): TaggedStatus | null {
	let best: TaggedStatus | null = null;
	for (const agent of agents) {
		const status = agentStatus(agent);
		if (hasStatusTag(status) && (best === null || TAG_PRIORITY.indexOf(status) < TAG_PRIORITY.indexOf(best))) best = status;
	}
	return best;
}

/**
 * The first `limit` agents in roster order, except that an agent needing
 * attention past the limit takes the place of the last calm row above it.
 * Only rows that need a person move, so the list never reshuffles on its own,
 * and it never grows past `limit`: once every row needs you, the rest wait
 * behind "More agents".
 */
function visibleRoster(agents: AgentSummary[], limit: number): AgentSummary[] {
	if (agents.length <= limit) return agents;
	const head = agents.slice(0, limit);
	const calm = head.filter((agent) => !needsAttention(agentStatus(agent))).length;
	const promoted = agents
		.slice(limit)
		.filter((agent) => needsAttention(agentStatus(agent)))
		.slice(0, calm);
	let room = promoted.length;
	const kept: AgentSummary[] = [];
	for (const agent of head.reverse()) {
		if (room > 0 && !needsAttention(agentStatus(agent))) room -= 1;
		else kept.unshift(agent);
	}
	return [...kept, ...promoted];
}

