				</div>
			</div>
			<ViewAnimation>
				<AgentRunSession
					key={session.attempt}
					script={session.attempt > 0 ? { ...run, failure: undefined } : run}
					start={session.start}
					active={active}
					queuedNote={session.queuedNote}
					panelOpen={panelOpen}
					onTogglePanel={() => setPanelOpen((value) => !value)}
					onRestart={() => setSession((current) => ({ ...current, attempt: current.attempt + 1, start: 'replay' }))}
				/>
