'use client';

import * as React from 'react';

import { CanvasWire, type WirePoint, type WireTone } from '@/components/ui/workspace-kit/canvas';
import { NODE_ANCHOR_Y as ANCHOR_Y } from '@/components/ui/agents-builder/canvas-nodes';
import type { AgentRunState } from '@/components/ui/agents-builder/use-agent-run';

/** Inputs wire from their right edge into the agent. */
const INPUTS: { id: string; tone: WireTone }[] = [
	{ id: 'schedule', tone: 'rest' },
	{ id: 'triggers', tone: 'live' },
	{ id: 'channels', tone: 'warn' },
	{ id: 'memory', tone: 'live' },
];
/** Outputs wire from the agent into their left edge; they glow while their stage loads. */
const OUTPUTS = ['tools', 'subagents', 'skills'] as const;

type Wire = { id: string; tone: WireTone; animated: boolean; start: WirePoint; end: WirePoint };

/** Offset of `node` within `layer`, ignoring transforms (so pan and zoom never skew it). */
function layerBox(layer: HTMLElement, node: HTMLElement) {
	let left = 0;
	let top = 0;
	for (let element: HTMLElement | null = node; element && element !== layer; element = element.offsetParent as HTMLElement | null) {
		left += element.offsetLeft;
		top += element.offsetTop;
	}
	return { left, right: left + node.offsetWidth, top };
}

type CanvasWiresProps = {
	stages: AgentRunState['nodes'];
	/** Changes whenever node sizes may change (collapse, "show more"), prompting a re-measure. */
	layoutKey: string;
	animate: boolean;
};

/**
 * Bezier wires between the agent and its inputs and outputs, measured from the
 * rendered nodes in untransformed layer coordinates. Render it as a direct
 * child of the transformed layer: the layer is found through the SVG's own
 * parent, which (unlike a parent ref) is available in the first layout effect.
 */
function CanvasWires({ stages, layoutKey, animate }: CanvasWiresProps) {
	const svgRef = React.useRef<SVGSVGElement>(null);
	const [wires, setWires] = React.useState<Wire[]>([]);

	React.useLayoutEffect(() => {
		const layer = svgRef.current?.parentElement;
		if (!layer) return;
		const measure = () => {
			const box = (id: string) => {
				const node = layer.querySelector<HTMLElement>(`[data-node-id="${id}"]`);
				return node && layerBox(layer, node);
			};
			const agent = box('agent');
			if (!agent) return setWires([]);
			const next: Wire[] = [];
			for (const { id, tone } of INPUTS) {
				const node = box(id);
				if (node) next.push({ id, tone, animated: false, start: [node.right, node.top + ANCHOR_Y], end: [agent.left, agent.top + ANCHOR_Y] });
			}
			for (const id of OUTPUTS) {
				const node = box(id);
				const loading = stages[id] === 'loading';
				if (node) next.push({ id, tone: loading ? 'live' : 'rest', animated: loading, start: [agent.right, agent.top + ANCHOR_Y], end: [node.left, node.top + ANCHOR_Y] });
			}
			setWires(next);
		};
		measure();
		const observer = new ResizeObserver(measure);
		layer.querySelectorAll('[data-node-id]').forEach((node) => observer.observe(node));
		return () => observer.disconnect();
	}, [layoutKey, stages]);

	return (
		<svg ref={svgRef} aria-hidden="true" className="pointer-events-none absolute top-0 start-0 overflow-visible" width="1" height="1">
			{wires.map((wire) => (
				<CanvasWire key={wire.id} start={wire.start} end={wire.end} tone={wire.tone} animated={wire.animated && animate} />
			))}
		</svg>
	);
}

export { CanvasWires };

'use client';

import { Square } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { AgentDraftCard } from '@/components/ui/ai/agent-draft-card';
import { AskCard } from '@/components/ui/ai/ask-card';
import { ConnectPrompt } from '@/components/ui/ai/connect-prompt';
import { ToolTrace } from '@/components/ui/ai/tool-trace';
import { useAgentsBuilder } from '@/components/ui/agents-builder/agents-builder-context';
import { IntegrationMark } from '@/components/ui/agents-builder/integration-mark';
import { enterClass, TooltipIconButton } from '@/components/ui/workspace-kit/primitives';
import { RevealText } from '@/components/ui/agents-builder/reveal-text';
import type { ToolStep } from '@/components/ui/agents-builder/types';
import { sayDuration, type ScriptedConversation, type ThreadItem } from '@/components/ui/agents-builder/use-scripted-conversation';

function traceStatus(index: number, done: number) {
	return index < done ? 'done' : index === done ? 'running' : 'pending';
}

function StepsTrace({ steps, done }: { steps: ToolStep[]; done: number }) {
	const { integration } = useAgentsBuilder();
	return (
		<ToolTrace
			steps={steps.map((step, index) => ({
				id: step.id,
				label: step.label,
				icon: <IntegrationMark integration={integration(step.integrationId)} bare />,
				status: traceStatus(index, done),
			}))}
		/>
	);
}

/**
 * The user's own words, kept as typed: line breaks and indentation survive and an
 * unbroken URL wraps instead of spilling out. The pinned opening message stays
 * three lines tall until expanded, so a pasted prompt cannot cover the thread.
 */
function UserMessage({ text, pinned, onStop }: { text: string; pinned: boolean; onStop?: () => void }) {
	const [expanded, setExpanded] = React.useState(false);
	const [clamped, setClamped] = React.useState(false);
	const body = React.useRef<HTMLParagraphElement>(null);
	React.useEffect(() => {
		const node = body.current;
		if (!node || !pinned || expanded) return;
		const measure = () => setClamped(node.scrollHeight > node.clientHeight + 1);
		measure();
		const observer = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(measure);
		observer?.observe(node);
		return () => observer?.disconnect();
	}, [expanded, pinned, text]);
	const card = (
		<div className={cn('flex min-h-12 items-center gap-3 rounded-xl bg-card py-2 pe-2 ps-3 shadow-card', !pinned && enterClass)}>
			<div className="min-w-0 flex-1">
				<p
					ref={body}
					className={cn(
						'text-sm text-pretty whitespace-pre-wrap text-foreground [overflow-wrap:anywhere]',
						pinned && !expanded && 'line-clamp-3',
						pinned && expanded && 'max-h-[40vh] overflow-y-auto',
					)}
				>
					{text}
				</p>
				{pinned && (clamped || expanded) ? (
					<button
						type="button"
						aria-expanded={expanded}
						onClick={() => setExpanded((current) => !current)}
						className="mt-1 cursor-pointer rounded-sm text-xs text-muted-foreground underline-offset-4 hover:text-foreground hover:underline focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-none"
					>
						{expanded ? 'Show less' : 'Show more'}
					</button>
				) : null}
			</div>
			{onStop ? (
				<TooltipIconButton label="Stop" className="bg-foreground text-background hover:bg-foreground/90 hover:text-background" onClick={onStop}>
					<Square aria-hidden="true" className="size-3 fill-current" />
				</TooltipIconButton>
			) : null}
		</div>
	);
	if (!pinned) return card;
	return (
		<div className="sticky top-0 z-20 -mb-4 bg-background pt-3">
			{card}
			<div aria-hidden="true" className="pointer-events-none h-4 bg-gradient-to-b from-background to-transparent" />
		</div>
	);
}

type ThreadEntryProps = {
	item: ThreadItem;
	/** The opening message pins to the top and carries the Stop control. */
	pinned: boolean;
	running: boolean;
	conversation: ScriptedConversation;
};

/** Renders one thread item. Agent-side items share a 12px inset so they align with the message text. */
function ThreadEntry({ item, pinned, running, conversation }: ThreadEntryProps) {
	const { integration, isConnected, requestConnect, emit } = useAgentsBuilder();

	if (item.kind === 'user') {
		return <UserMessage text={item.text} pinned={pinned} onStop={pinned && running ? conversation.stop : undefined} />;
	}

	const body = (() => {
		switch (item.kind) {
			case 'say':
				return <RevealText text={item.text} revealing={item.streaming} duration={sayDuration(item.text)} className="leading-6 text-foreground" />;
			case 'steps':
				return <StepsTrace steps={item.steps} done={item.done} />;
			case 'ask':
				return (
					<AskCard
						questions={item.beat.questions}
						answer={item.answer}
						onSubmit={(choices) => conversation.answer(item.id, { choices })}
						onSkip={() => conversation.answer(item.id, { skipped: true })}
					/>
				);
			case 'connect': {
				const { integrationId, skip } = item.beat;
				const app = integration(integrationId);
				const connected = () => conversation.resolveConnect(item.id, 'connected');
				return (
					<ConnectPrompt
						icon={<IntegrationMark integration={app} bare />}
						name={app?.name ?? integrationId}
						description={app?.description}
						status={item.status}
						skipLabel={skip.label}
						onSkip={() => conversation.resolveConnect(item.id, 'skipped')}
						onConnect={() => (isConnected(integrationId) ? connected() : requestConnect({ integrationId, onConnected: connected }))}
					/>
				);
			}
			case 'agent': {
				const { draft, options } = item.beat;
				return (
					<AgentDraftCard
						name={draft.name}
						schedule={draft.schedule}
						tools={draft.integrationIds.map((id) => ({
							id,
							label: integration(id)?.name ?? id,
							icon: <IntegrationMark integration={integration(id)} bare />,
						}))}
						steps={draft.steps}
						actions={options.map(({ id, label, chosenLabel }) => ({ id, label, chosenLabel }))}
						chosenActionId={item.chosen}
						onAction={(optionId) => {
							if (optionId === 'create') emit({ type: 'create-agent', draft });
							conversation.choose(item.id, optionId);
						}}
					/>
				);
			}
		}
	})();

	return <div className={cn('px-3', item.kind === 'say' && enterClass)}>{body}</div>;
}

