const RECOMMENDATION_ICONS: Record<ChatRecommendation['icon'], LucideIcon> = {
	file: FileText,
	'file-search': FileSearch,
	refresh: RefreshCw,
};

function RecommendationRow({ recommendation, onPick }: { recommendation: ChatRecommendation; onPick: () => void }) {
	const { integration } = useAgentsBuilder();
	const Icon = RECOMMENDATION_ICONS[recommendation.icon];
	const label = recommendation.parts
		.map((part) => (typeof part === 'string' ? part : part.integrationIds.map((id) => integration(id)?.name ?? id).join(' ')))
		.join(' ');

	return (
		<li>
			<button
				type="button"
				aria-label={label}
				onClick={onPick}
				className={cn(
					'flex min-h-8 w-full cursor-pointer flex-wrap items-center gap-x-2 gap-y-1 rounded-md px-1.5 py-1 text-start text-sm text-foreground hover:bg-overlay-hover pointer-coarse:min-h-11',
					focusRingClass,
				)}
			>
				<Icon aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
				{recommendation.parts.map((part, index) =>
					typeof part === 'string' ? (
						<span key={index}>{part}</span>
					) : (
						<span key={index} className="flex -space-x-1">
							{part.integrationIds.map((id) => (
								<IntegrationMark key={id} integration={integration(id)} size="xs" className="ring-2 ring-background" />
							))}
						</span>
					),
				)}
			</button>
		</li>
	);
}

/**
 * Chat home and thread. The home greets, offers recommendations, and starts a
 * scripted run; the thread plays replies with streamed prose, tool traces, and
 * inline questions until the person stops or answers.
 */
function ChatView() {
	const { data, emit } = useAgentsBuilder();
	const conversation = useScriptedConversation({ fallbackReply: data.fallbackReply, followUpReply: data.followUpReply });
	const [model, setModel] = React.useState<ModelSelection>(() => ({
		modelId: data.modelSections?.recentIds?.[0] ?? data.models[0]?.id ?? '',
	}));
	const { items, status } = conversation;
	const pinnedId = items.find((item) => item.kind === 'user')?.id;
	const recommendedId = React.useId();

	const composer = (placeholder: string, className?: string) => (
		<Composer
			surface="chat"
			ariaLabel="Message"
			placeholder={placeholder}
			model={model}
			onModelChange={setModel}
			className={className}
			onSubmit={(text) => conversation.send(text)}
		/>
	);

	return (
		<div className="flex min-w-0 flex-1 flex-col">
			<ViewHeader icon={MessageCircle} title="Chat" divider={false}>
				<Button
					size="xs"
					variant="outline"
					aria-label="New chat"
					disabled={items.length === 0}
					onClick={conversation.reset}
				>
					<Plus className="size-3.5" />
					<span className="hidden @md/view:inline">New chat</span>
				</Button>
				<TooltipIconButton label="Chat history" side="bottom" variant="raised" onClick={() => emit({ type: 'chat-history' })}>
					<History aria-hidden="true" className="size-3.5" />
				</TooltipIconButton>
			</ViewHeader>

			{items.length > 0 ? (
				<>
					<ChatContainer className="px-3 @md/view:px-4">
						<ChatContainerContent className="max-w-3xl gap-5 px-0 pt-0 pb-8">
							{items.map((item) => (
								<ThreadEntry
									key={item.id}
									item={item}
									pinned={item.id === pinnedId}
									running={status !== 'idle'}
									conversation={conversation}
								/>
							))}
							{status === 'running' ? (
								<ThinkingStatus className={cn('px-3', enterClass)} tokens={1200} tokensPerTick={40} />
							) : null}
						</ChatContainerContent>
						<ScrollButton className="sticky bottom-3 left-1/2 -translate-x-1/2" />
					</ChatContainer>
					<div className="shrink-0 px-3 pb-[max(0.75rem,env(safe-area-inset-bottom))] @md/view:px-4 @md/view:pb-4">
						{composer('Add a follow-up', 'mx-auto w-full max-w-3xl')}
					</div>
				</>
			) : (
				<div className="flex min-h-0 flex-1 flex-col overflow-y-auto px-3 @md/view:px-4">
					<div className="m-auto flex w-full max-w-3xl flex-col gap-6 py-6 @md/view:py-10">
						<div className="flex flex-col gap-4">
							<Mascot className={enterClass} />
							<h2 style={staggerStyle(1)} className={cn('text-balance text-xl font-medium tracking-tight text-foreground', enterClass)}>
								What should we look into?
							</h2>
						</div>
						<div style={staggerStyle(2)} className={enterClass}>
							{composer('Ask anything, or type @ to mention an agent')}
						</div>
						<section style={staggerStyle(3)} aria-labelledby={recommendedId} className={cn('flex flex-col gap-1', enterClass)}>
							<h2 id={recommendedId} className="px-1.5 text-[0.8125rem] text-muted-foreground">
								Recommended for you
							</h2>
							<ul aria-labelledby={recommendedId} className="flex flex-col">
								{data.recommendations.map((recommendation) => (
									<RecommendationRow
										key={recommendation.id}
										recommendation={recommendation}
										onPick={() => conversation.send(recommendation.prompt, recommendation.reply)}
									/>
								))}
							</ul>
						</section>
					</div>
				</div>
			)}
		</div>
	);
}

export { ChatView };

'use client';

import { ArrowUp, Paperclip, Sparkles } from 'lucide-react';
import * as React from 'react';

import { type AiModel, type ModelSelection, ModelSelector } from '@/components/ui/ai/model-selector';
import { PromptInput, PromptInputAction, PromptInputActions, PromptInputTextarea } from '@/components/ui/ai/prompt-input';
import { PromptInputTray } from '@/components/ui/ai/prompt-input-tray';
import { UsageNotice, usageTone } from '@/components/ui/ai/usage-notice';
import { Button } from '@/components/ui/button';
import { useAgentsBuilder } from '@/components/ui/agents-builder/agents-builder-context';
import { IntegrationMark } from '@/components/ui/agents-builder/integration-mark';

/** The AI kit model selector, fed from workspace data with integration marks as vendor icons. */
function ComposerModelSelector({ value, onChange }: { value: ModelSelection; onChange: (value: ModelSelection) => void }) {
	const { data, integration } = useAgentsBuilder();
	const models = React.useMemo<AiModel[]>(
		() =>
			data.models.map(({ integrationId, ...model }) => ({
				...model,
				icon: integrationId ? (
					<span className="text-[0.625rem]">
						<IntegrationMark integration={integration(integrationId)} bare />
					</span>
				) : model.provider === 'Router' ? (
					<Sparkles className="text-muted-foreground" />
				) : undefined,
			})),
		[data.models, integration],
	);
	return (
		<ModelSelector
			models={models}
			value={value}
			onValueChange={onChange}
			pinnedIds={data.modelSections?.pinnedIds}
			recentIds={data.modelSections?.recentIds}
			recommendedIds={data.modelSections?.recommendedIds}
			triggerClassName="h-7 min-w-0 px-1.5"
		/>
	);
}

type ComposerProps = {
	placeholder: string;
	ariaLabel: string;
	onSubmit: (text: string) => void;
	surface: 'chat' | 'run';
	/** Selected model and reasoning level. Shows the model picker when set; the run panel omits it. */
	model?: ModelSelection;
	onModelChange?: (value: ModelSelection) => void;
	className?: string;
};

/**
 * Composer shared by chat and the run panel: budget notice, autosizing
 * textarea, attach, optional model picker, and a send button that only lights
 * up once there is something to send.
 */
function Composer({ placeholder, ariaLabel, onSubmit, surface, model, onModelChange, className }: ComposerProps) {
	const { data, emit, usageDismissed, dismissUsage } = useAgentsBuilder();
	const [value, setValue] = React.useState('');
	const canSend = value.trim().length > 0;

	const submit = () => {
		if (!canSend) return;
		onSubmit(value.trim());
		setValue('');
	};

	return (
		<div className={className}>
			<PromptInputTray
				tone={usageTone(data.usage.percent)}
				header={
					usageDismissed ? null : (
						<UsageNotice
							percent={data.usage.percent}
							onAction={() => emit({ type: 'navigate', target: 'usage' })}
							onDismiss={dismissUsage}
						/>
					)
				}
			>
				<PromptInput
					value={value}
					onValueChange={setValue}
					onSubmit={submit}
					className="rounded-xl border-border bg-card p-1.5 shadow-sm"
				>
					<PromptInputTextarea
						aria-label={ariaLabel}
						placeholder={placeholder}
						className="min-h-9 px-1.5 py-1"
					/>
					<PromptInputActions className="justify-between px-0">
						{/* min-w-0 lets a long model name truncate inside the picker instead of pushing Send out of the card. */}
						<div className="flex min-w-0 flex-1 items-center gap-1">
							<PromptInputAction tooltip="Attach a file">
								<Button
									size="icon-xs"
									variant="outline"
									aria-label="Attach a file"
									className="size-7 shrink-0"
									onClick={() => emit({ type: 'attach-file', surface })}
								>
									<Paperclip className="size-3.5" />
								</Button>
							</PromptInputAction>
							{model && onModelChange ? <ComposerModelSelector value={model} onChange={onModelChange} /> : null}
						</div>
						<PromptInputAction tooltip="Send">
							<Button
								size="icon-xs"
								variant={canSend ? 'default' : 'secondary'}
								aria-label="Send"
								disabled={!canSend}
								className="size-7 shrink-0"
								onClick={submit}
							>
								<ArrowUp className="size-3.5" />
							</Button>
						</PromptInputAction>
					</PromptInputActions>
				</PromptInput>
			</PromptInputTray>
		</div>
	);
}

export { Composer };

'use client';

import { Check } from 'lucide-react';
import * as React from 'react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Dialog, DialogDescription, DialogPopup, DialogTitle } from '@/components/ui/dialog';
import { Spinner } from '@/components/ui/spinner';
import { Switch } from '@/components/ui/switch';
import { IntegrationMark } from '@/components/ui/agents-builder/integration-mark';
import { focusRingClass } from '@/components/ui/workspace-kit/primitives';
import type { Integration } from '@/components/ui/agents-builder/types';
import { startViewTransition, ViewAnimation } from '@/components/ui/workspace-kit/view-transition';

type Phase = 'sign-in' | 'authorizing' | 'tools' | 'connecting';

type ConnectIntegrationDialogProps = {
	integration: Integration | undefined;
	appName: string;
	open: boolean;
	onOpenChange: (open: boolean) => void;
	/**
	 * Runs the real OAuth handoff. Resolve when the provider redirects back;
	 * the dialog then asks which tools agents may use.
	 */
	onAuthorize?: (integration: Integration) => Promise<void>;
	/** Persists the connection with the tools the person left enabled. */
	onConnect: (integration: Integration, toolIds: string[]) => void | Promise<void>;
};

function StepMarker({ index, state }: { index: number; state: 'active' | 'done' | 'upcoming' }) {
	return (
		<span
			aria-hidden="true"
			className={cn(
				'grid size-6 shrink-0 place-items-center rounded-full border text-xs tabular-nums',
				state === 'active' && 'border-primary text-foreground',
				state === 'done' && 'border-transparent bg-muted text-foreground',
				state === 'upcoming' && 'border-border text-muted-foreground',
			)}
		>
			{state === 'done' ? <Check className="size-3.5" /> : index}
		</span>
	);
}

const simulateAuthorize = () => new Promise<void>((resolve) => window.setTimeout(resolve, 1400));

type ConnectFlowProps = Omit<ConnectIntegrationDialogProps, 'integration' | 'open' | 'onOpenChange'> & {
	integration: Integration;
	onDone: () => void;
};

/** Dialog body. Keyed per integration and unmounted on close, so every visit starts at sign-in. */
function ConnectFlow({ integration, appName, onAuthorize = simulateAuthorize, onConnect, onDone }: ConnectFlowProps) {
	const [phase, setPhase] = React.useState<Phase>('sign-in');
	const [enabled, setEnabled] = React.useState<ReadonlySet<string>>(() => new Set(integration.tools.map((tool) => tool.id)));

	const authorize = async () => {
		setPhase('authorizing');
		try {
			await onAuthorize(integration);
			startViewTransition(() => setPhase('tools'));
		} catch {
			setPhase('sign-in');
		}
	};

	const connect = async () => {
		setPhase('connecting');
		try {
			await onConnect(integration, [...enabled]);
			onDone();
		} catch {
			setPhase('tools');
		}
	};

	const toggleTool = (toolId: string, checked: boolean) =>
		setEnabled((current) => {
			const next = new Set(current);
			if (checked) next.add(toolId);
			else next.delete(toolId);
			return next;
		});

	const signedIn = phase === 'tools' || phase === 'connecting';
	const toolCount = integration.tools.length;

	return (
		<div className="flex flex-col gap-5 p-5">
			<div className="flex flex-col gap-3">
				<IntegrationMark integration={integration} size="md" />
				<div className="flex flex-col gap-1">
					<DialogTitle className="text-base font-medium">Connect {integration.name}</DialogTitle>
					<DialogDescription className="text-[0.8125rem]">
						Your agents get <span className="tabular-nums">{toolCount}</span> new {toolCount === 1 ? 'tool' : 'tools'} once
						this is connected
					</DialogDescription>
				</div>
			</div>

			<ol className="flex flex-col">
				<li className="flex gap-3">
					<div className="flex flex-col items-center">
						<StepMarker index={1} state={signedIn ? 'done' : 'active'} />
						<span aria-hidden="true" className="my-1 w-px flex-1 border-s border-dashed border-border" />
					</div>
					<div className="min-w-0 flex-1 pb-5">
						<p className={cn('flex h-6 items-center text-sm', signedIn ? 'text-muted-foreground' : 'font-medium text-foreground')}>
							Sign in
						</p>
						{phase === 'sign-in' ? (
							<div className="mt-2 flex flex-col gap-3">
								<p className="text-[0.8125rem] text-muted-foreground">
									Authorization happens on {integration.vendor}&apos;s side. Takes about a minute
								</p>
								<ul className="divide-y divide-border overflow-hidden rounded-lg border border-border text-[0.8125rem] text-foreground">
									<li className="flex min-h-10 flex-wrap items-center gap-1 px-3 py-2">
										A new tab opens at
										<span className="inline-flex h-5 items-center rounded-[5px] border border-border bg-muted px-1 font-mono text-xs">
											{integration.authDomain}
										</span>
									</li>
									<li className="flex min-h-10 items-center px-3 py-2">
										You approve there. {integration.vendor} asks whether {appName} can read your account
									</li>
									<li className="flex min-h-10 items-center px-3 py-2">
										You come back here. Then you choose which tools agents can use
									</li>
								</ul>
								<Button size="sm" className="self-start" onClick={authorize}>
									Sign in to {integration.name}
								</Button>
							</div>
						) : null}
						{phase === 'authorizing' ? (
							<div className="mt-2 flex flex-col gap-2">
								<p role="status" className="flex h-10 items-center gap-2 rounded-lg border border-border px-3 text-[0.8125rem] text-foreground">
									<Spinner aria-hidden="true" role={undefined} className="size-3.5 text-muted-foreground" strokeWidth={1.5} />
									Authorizing
								</p>
								<p className="text-[0.8125rem] text-muted-foreground">
									Window not showing up?{' '}
									<button
										type="button"
										onClick={authorize}
										className={cn('cursor-pointer rounded-sm text-link hover:underline', focusRingClass)}
									>
										Reopen it
									</button>
								</p>
							</div>
						) : null}
					</div>
				</li>
				<li className="flex gap-3">
					<StepMarker index={2} state={signedIn ? 'active' : 'upcoming'} />
					<div className="min-w-0 flex-1">
						<p className={cn('flex h-6 items-center text-sm', signedIn ? 'font-medium text-foreground' : 'text-muted-foreground')}>
							Tools
						</p>
						{signedIn ? (
							<div className="mt-2 flex flex-col gap-3">
								<ul className="divide-y divide-border overflow-hidden rounded-lg border border-border">
									{integration.tools.map((tool) => {
										const id = `connect-${integration.id}-${tool.id}`;
										return (
											<li key={tool.id} className="flex h-11 items-center gap-2 pe-1 ps-3">
												<label htmlFor={id} className="min-w-0 flex-1 truncate text-[0.8125rem] text-foreground">
													{tool.name}
												</label>
												<span
													className={cn(
														'inline-flex h-5 items-center rounded-[5px] border px-1.5 text-xs',
														tool.access === 'write'
															? 'border-primary/30 bg-primary/6 text-link'
															: 'border-border text-muted-foreground',
													)}
												>
													{tool.access === 'write' ? 'Write' : 'Read'}
												</span>
												<Switch
													id={id}
													checked={enabled.has(tool.id)}
													disabled={phase === 'connecting'}
													onCheckedChange={(checked) => toggleTool(tool.id, checked)}
												/>
											</li>
										);
									})}
								</ul>
								<div className="flex items-center gap-2">
									<Button size="sm" disabled={phase === 'connecting' || enabled.size === 0} onClick={connect}>
										Connect {integration.name}
									</Button>
									<Button size="sm" variant="outline" disabled={phase === 'connecting'} onClick={onDone}>
										Cancel
									</Button>
								</div>
							</div>
						) : null}
					</div>
				</li>
			</ol>
		</div>
	);
}

/**
 * Two-step connect flow: hand off to the provider's consent screen, then pick
 * which of the app's tools agents may call. The host performs both calls.
 */
function ConnectIntegrationDialog({ integration, open, onOpenChange, ...flow }: ConnectIntegrationDialogProps) {
	return (
		<Dialog open={open} onOpenChange={onOpenChange}>
			{integration ? (
				<DialogPopup className="max-w-md">
					<ViewAnimation>
						<div>
							<ConnectFlow key={integration.id} integration={integration} onDone={() => onOpenChange(false)} {...flow} />
						</div>
					</ViewAnimation>
				</DialogPopup>
			) : null}
		</Dialog>
	);
}

export { ConnectIntegrationDialog };
export type { ConnectIntegrationDialogProps };

import type { AskBeatQuestion, ChatRecommendation, ConversationBeat } from '@/components/ui/agents-builder/types';

// Scripted chat for the demo analytics workspace: three recommended prompts with
// branching replies, plus the replies to free-form messages.

function reviewFollowUp(count: 2 | 3): ConversationBeat {
	const word = count === 3 ? 'Three' : 'Two';
	const comments = { id: 'github-comments', label: `GitHub Post ${count} review comments`, integrationId: 'github' };
	const issues = { id: 'linear-issues', label: `Linear Create ${count} issues`, integrationId: 'linear' };
	const questions: AskBeatQuestion[] = [
		{
			id: 'how-do-you-want-them-back',
			question: 'How do you want them back?',
			options: [
				{
					id: 'comments',
					label: 'Comment on the PR',
					then: [
						{ kind: 'steps', steps: [comments] },
						{ kind: 'say', text: `Done. ${word} comments, each on its line, and the PR is marked Changes requested.` },
					],
				},
				{
					id: 'issues',
					label: 'Issues in Linear',
					then: [
						{ kind: 'steps', steps: [issues] },
						{ kind: 'say', text: `Done. ${word} issues for Data platform, each linked to its line in the PR.` },
					],
				},
				{
					id: 'both',
					label: 'Both',
					then: [
						{ kind: 'steps', steps: [comments, issues] },
						{
							kind: 'say',
							text: 'Both done: a comment on each line and an issue for each, linked to one another, so resolving one closes the other.',
						},
					],
				},
			],
		},
		{
			id: 'the-merge',
			question: 'And the merge?',
			options: [
				{
					id: 'block',
					label: 'Block until fixed',
					then: [{ kind: 'say', text: 'Merge is blocked by a required check that clears once the comments are resolved.' }],
				},
				{
					id: 'leave',
					label: 'Leave it to the author',
					then: [{ kind: 'say', text: 'Left to the author. The findings are on the PR when they look.' }],
				},
			],
		},
	];
	return {
		kind: 'ask',
		questions,
		onSkip: [{ kind: 'say', text: 'Left as they are: the findings are here whenever you want them filed.' }],
	};
}

