type IntegrationMarkProps = {
	integration: Pick<Integration, 'name' | 'mark' | 'color'> | undefined;
	/** Glyph only, for placing inside an existing tile (tool traces, drafts). */
	bare?: boolean;
	size?: 'xs' | 'sm' | 'md';
	className?: string;
};

/** The first letter of the name in any script (`Évernote` is É, `ВКонтакте` is В), or "?" when there is none. */
function monogram(name: string) {
	return initials(name, { max: 1 }) ?? '?';
}

/**
 * App mark for an integration. Hosts pass real brand marks through
 * `integration.mark`; otherwise a monogram tinted with `integration.color`
 * keeps every app recognizable without shipping third-party logos. The tint
 * mixes toward the foreground more in dark mode so dark brand colors stay
 * legible.
 */
function IntegrationMark({ integration, bare, size = 'sm', className }: IntegrationMarkProps) {
	const color = integration?.color;
	const glyph = integration?.mark ?? (
		<span
			className="font-semibold leading-none [--mark-mix:22%] dark:[--mark-mix:50%]"
			style={color ? { color: `color-mix(in oklab, ${color}, var(--foreground) var(--mark-mix))` } : undefined}
		>
			{monogram(integration?.name ?? '')}
		</span>
	);

	if (bare) return glyph;

	return (
		<MarkTile
			data-slot="integration-mark"
			size={size}
			className={cn('text-foreground', className)}
			style={color && !integration?.mark ? { backgroundColor: `color-mix(in oklab, ${color} 14%, var(--card))` } : undefined}
		>
			{glyph}
		</MarkTile>
	);
}

export { IntegrationMark };
export type { IntegrationMarkProps };

import type { Integration, IntegrationCategory } from '@/components/ui/agents-builder/types';

export type IntegrationScope = 'all' | 'connected';

export type IntegrationSection = { id: string; label: string; items: Integration[] };

type SectionOptions = {
	scope: IntegrationScope;
	query: string;
	isConnected: (id: string) => boolean;
};

function matchesQuery(integration: Integration, term: string) {
	return `${integration.name} ${integration.description} ${integration.vendor}`.toLowerCase().includes(term);
}

/**
 * Groups the directory into sections. Browsing everything leads with a
 * Recommended section and keeps those apps out of their categories; filtering
 * (connected only, or a search) lists every match in its category, with model
 * providers last.
 */
export function buildIntegrationSections(
	integrations: Integration[],
	categories: IntegrationCategory[],
	{ scope, query, isConnected }: SectionOptions,
): IntegrationSection[] {
	const term = query.trim().toLowerCase();
	const browsing = scope === 'all' && !term;
	const recommended: Integration[] = [];
	const grouped = new Map<string, Integration[]>();

	for (const integration of integrations) {
		if (scope === 'connected' && !isConnected(integration.id)) continue;
		if (term && !matchesQuery(integration, term)) continue;
		if (browsing && integration.recommended) {
			recommended.push(integration);
			continue;
		}
		const key = integration.categoryId ?? (browsing ? null : 'models');
		if (!key) continue;
		const group = grouped.get(key);
		if (group) group.push(integration);
		else grouped.set(key, [integration]);
	}

	return [
		{ id: 'recommended', label: 'Recommended', items: recommended },
		...categories.map((category) => ({ ...category, items: grouped.get(category.id) ?? [] })),
		{ id: 'models', label: 'Models', items: grouped.get('models') ?? [] },
	].filter((section) => section.items.length > 0);
}

